body.script:
function handleFileInputChange(event) {
    const file = event.target.files[0];
    if (file) {
        const reader = new FileReader();

        reader.onload = function(e) {
            // Update the profile image source
            const img = document.getElementById('profile-img');
            if (img) {
                img.src = e.target.result;
            } else {
                const imgTag = document.createElement('img');
                imgTag.src = e.target.result;
                imgTag.id = 'profile-img';
                imgTag.alt = 'Profile';
                imgTag.style.height = '64px';
                imgTag.style.borderRadius = '50px';

                const container = document.querySelector('.fv_profile_img');
                container.innerHTML = ''; 
                container.appendChild(imgTag);
                container.appendChild(document.getElementById('upload-svg'));
            }
        };

        reader.readAsDataURL(file);
    }
}

document.getElementById('upload-svg').addEventListener('click', function() {
    document.getElementById('file-input').click();
});
document.getElementById('file-input').addEventListener('change', handleFileInputChange);

document.addEventListener('DOMContentLoaded', function() {
    const revokeLinks = document.querySelectorAll('.revoke-access');

    revokeLinks.forEach(link => {
        link.addEventListener('click', function() {
            const recordName = this.getAttribute('data-record-name');
            const recordPhone = this.getAttribute('data-record-phone');

            document.getElementById('revoke_contact_name').value = recordName;
            document.getElementById('revoke_contact_phone').value = recordPhone;
        });
    });
});

document.getElementById("btn-collapse").onclick = function() {  
    toggleAside()  
  };
  function toggleAside() {
    var asideElement = document.getElementById("sidebar");
    var isCollapsed = asideElement.classList.contains("collapsed");

    if (isCollapsed) {
      document.getElementById('side-bar-id').style.display='block';   
      document.getElementById('loadingImage').style.visibility='hidden';  
    } 
    else {
      document.getElementById('side-bar-id').style.display='none';   
      document.getElementById('loadingImage').style.visibility='visible';
    }
  }
  $(function(){
  $(".fold-table tr.view").on("click", function(){
    $(this).toggleClass("open").next(".fold").toggleClass("open");
  });
});

    document.addEventListener('DOMContentLoaded', function() {
    const emailVerifyLinks = document.querySelectorAll('.verify_email_number');
    const phoneVerifyLinks = document.querySelectorAll('.verify_phone_number');

    emailVerifyLinks.forEach(function(link) {
        link.addEventListener('click', function(event) {
            const recordId = event.target.getAttribute('data-record-id');
            const formId = 'email_verification_form_' + recordId;
            document.getElementById(formId).submit();
        });
    });

    phoneVerifyLinks.forEach(function(link) {
        link.addEventListener('click', function(event) {
            const recordId = event.target.getAttribute('data-record-id');
            const formId = 'phone_verification_form_' + recordId;
            document.getElementById(formId).submit();
        });
    });
});


        document.addEventListener('DOMContentLoaded', function() {
    var verifyButtons = document.querySelectorAll('.verify_phone');

    verifyButtons.forEach(function(button) {
        button.addEventListener('click', function() {
            var userName = this.getAttribute('data-name');
            var userPhone = this.getAttribute('data-phone');
            var nameAttr = this.getAttribute('name');
            var valueAttr = this.getAttribute('value');
            resendOTP(userName, userPhone, nameAttr, valueAttr);
        });
    });
});

function resendOTP(userName, userPhone, nameAttr, valueAttr) {
    fetch('/vendor/setting/phone/check', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: `contact_name=${encodeURIComponent(userName)}&phone=${encodeURIComponent(userPhone)}&${encodeURIComponent(nameAttr)}=${encodeURIComponent(valueAttr)}`
    })
    .then(response => response.text())
    .then(data => {
    console.log(data.includes('client_vendor_dashboard.check_phone_number_form_template'))

        if (data.includes('client_vendor_dashboard.check_phone_number_form_template')) {
            var redirectUrl = '/vendor/setting/phone/check'; 
            window.location.href = redirectUrl;
        } else {
         console.log(" ===================inside else block==================")

      console.log('Response:', data); 
        }
    })
    .catch(error => {
        console.error('Error:', error);
    });
}




const allMenu = document.querySelectorAll('.menu1'); 

allMenu.forEach(item => {
    const icon = item.querySelector('.icon');
    const menuLink = item.querySelector('.menu1-link');

    icon.addEventListener('click', function() {
        menuLink.classList.toggle('show');
    });
});

window.addEventListener('click', function(e) {
    allMenu.forEach(item => {
        const icon = item.querySelector('.icon');
        const menuLink = item.querySelector('.menu1-link');

        if (e.target !== icon && e.target !== menuLink) {
            if (menuLink.classList.contains('show')) {
                menuLink.classList.remove('show');
            }
        }
    });
});

var tabButtons = document.querySelectorAll(".tablinks");
for (var i = 0; i < tabButtons.length; i++) {
  tabButtons[i].addEventListener("click", function () {
    var tabName = this.dataset.tab;
    var tabContent = document.getElementById(tabName);
    var allTabContent = document.querySelectorAll(".tabcontent");
    var allTabButtons = document.querySelectorAll(".tablinks");

    for (var j = 0; j < allTabContent.length; j++) {
      allTabContent[j].style.display = "none";
    }

    for (var k = 0; k < allTabButtons.length; k++) {
      allTabButtons[k].classList.remove("active");
    }

    tabContent.style.display = "block";
    this.classList.add("active");
  });
}
document.querySelector(".tablinks").click();

document.addEventListener('DOMContentLoaded', function() {
    const eyeIcon = document.getElementById('eyeIconconfirm');
    const passwordInput = document.querySelector('.password-input');
    eyeIcon.addEventListener('click', function() {
        if (passwordInput.type === 'password') {
            passwordInput.type = 'text';
            eyeIcon.querySelector('path').setAttribute('fill', '#000'); 
        } else {
            passwordInput.type = 'password';
            eyeIcon.querySelector('path').setAttribute('fill', '#919496');
        }
    });
});
